use crate::chess::Position;
use crate::perft;
use std::str::FromStr;

macro_rules! perft_test {
    ($name:ident $pos:literal $depth:literal $nodes:literal) => {
        #[test]
        fn $name() {
            let position = Position::from_str($pos).unwrap();
            assert_eq!(perft::<true, true, _>(position, $depth), $nodes)
        }
    };
}

